// 상황별 주민 대사 — 날씨·시간·계절·기념일·플레이어 상태·섬 사건에 따라 말을 걸 때 첫마디가 달라져요.
// 상황 id 는 index.html 의 situationsNow() 에서 판단하고, 여기서는 주민별 대사만 둬요.
// {name} 은 플레이어 닉네임, {item} 은 상황에 따라 채워지는 이름(인기 품목·작물 등)으로 바뀌어요.
//
// 상황 목록
//  날씨: rain 비 / cloudy 흐림 / rainbow 무지개 / sunny 맑음(한낮)
//  시간: dawn 새벽 0~5 시 / weekend 주말
//  계절: spring 3~5월 / summer 6~8월 / autumn 9~11월 / winter 12~2월
//  기념일: newyear 1/1 / valentine 2/14 / whiteday 3/14 / childrens 5/5 / halloween 10/31 / pepero 11/11 / xmas 12/24~25 / yearend 12/31
//  플레이어: firstEver 첫 만남 / longAbsence 3 일 이상 안 옴 / lowHp 체력 40 미만 / rich 5만G 이상 / broke 30 G 미만
//           bagHeavy 가방 꽉 참 / hasFish·hasOre·hasLoot 가방 속 물건 / wearHat 모자 / wearSet 세트 옷 / hasTitle 칭호 / strongWeapon 상급 무기
//           cropsReady 수확할 작물 / gardenDry 물 안 준 작물 / manyFurn 가구 15 개 이상 / achMany 업적 20 개 이상
//  관계·퀘스트: giftedToday 오늘 선물함 / questActive 이 주민 심부름 진행 중 / questAllDone 이 주민 이야기 전부 끝
//  섬 사건: bossAlive 먼지 여왕 출현 / bossDown 먼지 여왕 격퇴 / hotItem 오늘 인기 품목을 갖고 있음
