      "있잖아 있잖아! 비 와서 편지 다 젖을 뻔했어! 그래서 말이야 가방에 비닐 씌웠거든!\n(젖은 꼬리를 탈탈 턴다) 편지는 뽀송뽀송, 나는 흠뻑! 우체부는 편지가 먼저야!\n헤헤, 꼬리 마르면 두 배로 부풀 거야!",
      "비 오는 날 배달은 진짜 힘들어! 근데 있잖아, 모모네서 우산 빌려줬어! 다정하지!\n빵 냄새 나는 노란 우산이야! 쓰고 다니니까 배가 자꾸 고파져!\n그래서 말이야, 이따 돌려줄 때 빵 하나 살 거야!"
