      "그래서 말이야, 섬에서 네 집이 제일 예뻐! 소문냈어!\n모모도 구경 가고 싶대고 콩이는 순찰 코스에 넣는대!\n(헤헤 웃는다) 이러다 네 집이 섬 관광지 되겠다! 그럼 나 안내원 할게!"
