      "오랜만이야. 펭, 그동안 바람이 세 번 바뀌었어. 북풍, 서풍, 또 북풍.\n네가 없는 동안 수첩에 네 얘기도 썼어.\n\"오늘도 안 옴. 날씨는 맑은데 마음은 구름 조금.\" 이런 거."
